package cn.local.starward;
import android.app.*;
import android.os.Bundle;
import android.content.Intent;
import android.net.Uri;
import android.webkit.*;
import android.graphics.Color;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;

public class BattleActivity extends Activity {
    @Override protected void onResume(){super.onResume();callback("window.collectOfficialInbox&&window.collectOfficialInbox()");consumeRefreshResult();}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);consumeRefreshResult();}
    private void consumeRefreshResult(){String text=getIntent().getStringExtra("battle-refresh-result");if(text!=null){getIntent().removeExtra("battle-refresh-result");try{JSONObject result=new JSONObject(text);callback("window.finishBattleRefresh&&window.finishBattleRefresh("+result.toString()+")");}catch(JSONException e){status("刷新状态无法读取；已取得结果会在返回时自动导入。");}}}
    private WebView web;private String exportText;private boolean pageReady=false;private final List<String> pendingUi=new ArrayList<>();private final ExecutorService executor=Executors.newSingleThreadExecutor();
    private final ExecutorService rankExecutor=Executors.newFixedThreadPool(2);
    private static final int IMPORT=101,EXPORT=102,OFFICIAL=103,MAX=64*1024*1024;
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(Color.rgb(32,55,78));getWindow().setNavigationBarColor(Color.rgb(240,245,239));web=new WebView(this);web.setBackgroundColor(Color.rgb(240,245,239));WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setTextZoom(100);settings.setMinimumFontSize(1);settings.setMinimumLogicalFontSize(1);settings.setDomStorageEnabled(false);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setAllowFileAccessFromFileURLs(false);settings.setAllowUniversalAccessFromFileURLs(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView view,String url){pageReady=true;for(String script:pendingUi)web.evaluateJavascript(script,null);pendingUi.clear();}@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){return true;}@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){if(request.getUrl().toString().startsWith("file:///android_asset/")||request.getUrl().toString().startsWith("data:image/")||request.getUrl().toString().startsWith("https://sres.shengtiangames.com/uploads/"))return null;return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}});if(android.os.Build.VERSION.SDK_INT>=35)web.setOnApplyWindowInsetsListener((view,insets)->{view.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});web.addJavascriptInterface(new Bridge(),"Android");setContentView(web);web.loadUrl("file:///android_asset/index.html");if(android.os.Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,()->goBack());}
    private String read(InputStream input)throws IOException{if(input==null)throw new IOException("无法读取文件");try(InputStream in=input;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1){if(out.size()+n>MAX)throw new IOException("文件超过 64 MB");out.write(bytes,0,n);}return new String(out.toByteArray(),StandardCharsets.UTF_8);}}
    private void write(AtomicFile file,String text)throws IOException{FileOutputStream out=null;try{out=file.startWrite();out.write(text.getBytes(StandardCharsets.UTF_8));file.finishWrite(out);}catch(Exception e){if(out!=null)file.failWrite(out);throw new IOException(e);}}
    private AtomicFile dbFile(){return new AtomicFile(new File(getFilesDir(),"battles.json"));}
    private AtomicFile backupFile(){return new AtomicFile(new File(getFilesDir(),"before-import.json"));}
    private void callback(String script){runOnUiThread(()->{if(web!=null){if(pageReady)web.evaluateJavascript(script,null);else pendingUi.add(script);}});}
    private void status(String text){callback("window.nativeStatus("+JSONObject.quote(text)+")");}
    private class Bridge {
        @JavascriptInterface public String readRankCache(){return LeaderboardService.readCache(BattleActivity.this);}
        @JavascriptInterface public String saveRankCache(String text){return LeaderboardService.saveCache(BattleActivity.this,text);}
        @JavascriptInterface public void requestRank(final String id,final String endpoint,final String query){rankExecutor.execute(()->{String text="",error="";try{if(id==null||id.length()>80||query==null||query.length()>300)throw new IOException("排行榜请求无效");text=LeaderboardService.fetch(endpoint,query);}catch(Exception e){error="官网读取失败："+e.getMessage();}callback("window.resolveRankRequest("+JSONObject.quote(id)+","+JSONObject.quote(text)+","+JSONObject.quote(error)+")");});}

        @JavascriptInterface public String getColorTheme(){return getPreferences(MODE_PRIVATE).getString("colorTheme","light");}
        @JavascriptInterface public void setColorTheme(String value){if(!Arrays.asList("light","dark").contains(value))return;getPreferences(MODE_PRIVATE).edit().putString("colorTheme",value).apply();runOnUiThread(()->{boolean dark="dark".equals(value);getWindow().setStatusBarColor(dark?Color.rgb(18,32,44):Color.rgb(32,55,78));getWindow().setNavigationBarColor(dark?Color.rgb(15,27,36):Color.rgb(240,245,239));if(web!=null)web.setBackgroundColor(dark?Color.rgb(15,27,36):Color.rgb(240,245,239));});}

        @JavascriptInterface public String getFontScale(){return getPreferences(MODE_PRIVATE).getString("fontScale","1");}
        @JavascriptInterface public void setFontScale(String value){if(Arrays.asList("0.5","0.6","0.75","0.9","1","1.25","1.5").contains(value))getPreferences(MODE_PRIVATE).edit().putString("fontScale",value).apply();}

        @JavascriptInterface public synchronized String readDatabase(){try{AtomicFile file=dbFile();if(file.getBaseFile().exists()||new File(file.getBaseFile()+".bak").exists())return read(file.openRead());return "{\"Format\":\"XZY-BattleArchive\",\"Version\":1,\"Snapshots\":[]}";}catch(Exception e){return "{\"Error\":\"缓存无法读取，请恢复备份\"}";}}
        @JavascriptInterface public synchronized String saveDatabase(String text){try{if(text.getBytes(StandardCharsets.UTF_8).length>MAX)throw new IOException("本机数据库超过 64 MB，请先导出备份");JSONObject obj=new JSONObject(text);if(!"XZY-BattleArchive".equals(obj.getString("Format"))||obj.getInt("Version")!=1||obj.getJSONArray("Snapshots").length()>500)throw new IOException("数据库格式无效");AtomicFile file=dbFile();if(file.getBaseFile().exists())write(backupFile(),read(file.openRead()));write(file,text);return "";}catch(Exception e){return "保存失败："+e.getMessage();}}
        @JavascriptInterface public String fingerprint(String text){try{byte[] hash=MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte b:hash)out.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return out.toString();}catch(Exception e){throw new IllegalStateException(e);}}
        @JavascriptInterface public String readDemo(){try{return read(getAssets().open("demo.json"));}catch(Exception e){throw new IllegalStateException(e);}}
        @JavascriptInterface public void exportFile(String name,String mime,String text){runOnUiThread(()->{if(exportText!=null){status("请先完成或取消当前导出");return;}if(text.getBytes(StandardCharsets.UTF_8).length>MAX){status("文件超过 64 MB");return;}exportText=text;try{Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("text/csv".equals(mime)?"text/csv":"application/json");intent.putExtra(Intent.EXTRA_TITLE,name.replaceAll("[\\\\/:*?\"<>|]","_"));startActivityForResult(intent,EXPORT);}catch(Exception e){exportText=null;status("打开文件选择器失败："+e.getMessage());}});}
        @JavascriptInterface public void importFile(){runOnUiThread(()->{try{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("*/*");intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(intent,IMPORT);}catch(Exception e){status("打开文件选择器失败："+e.getMessage());}});}
        @JavascriptInterface public void openOfficial(){runOnUiThread(()->OfficialProfiles.choose(BattleActivity.this));}
        @JavascriptInterface public synchronized void refreshBattles(String spec){String request="";try{JSONObject target=new JSONObject(spec);String uid=target.getString("Uid"),game=target.getString("GameCode");request=target.getString("RequestId");int season=target.getInt("SeasonCode");if(request.length()>100||!request.matches("battle-[0-9-]+")||season<1||season>1000)throw new JSONException("刷新参数无效");JSONObject database=new JSONObject(readDatabase());JSONArray snapshots=database.getJSONArray("Snapshots");boolean found=false;for(int i=0;i<snapshots.length();i++){JSONObject s=snapshots.getJSONObject(i);if(!s.optBoolean("Demo",false)&&uid.equals(s.optString("Uid"))&&game.equals(s.optString("GameCode"))&&season==s.optInt("SeasonCode")){found=true;break;}}if(!found)throw new JSONException("目标账号赛季不在已导入数据中");String safe=target.toString();runOnUiThread(()->OfficialProfiles.refresh(BattleActivity.this,safe));}catch(Exception e){callback("window.finishBattleRefresh({RequestId:"+JSONObject.quote(request)+",Success:false,Saved:false,Message:"+JSONObject.quote("无法刷新："+e.getMessage())+"})");}}
        @JavascriptInterface public synchronized String readOfficialInbox(){try{return OfficialInbox.read(BattleActivity.this);}catch(Exception e){throw new IllegalStateException(e);}}
        @JavascriptInterface public synchronized String ackOfficialInbox(String id){try{OfficialInbox.ack(BattleActivity.this,id);return "";}catch(Exception e){return e.getMessage();}}
        @JavascriptInterface public void closeApp(){runOnUiThread(()->finish());}
        @JavascriptInterface public void restoreBackup(){runOnUiThread(()->new AlertDialog.Builder(BattleActivity.this).setTitle("恢复上次导入前备份").setMessage("将恢复上一次成功导入之前的全部账号和赛季。建议先导出当前数据备份。").setNegativeButton("取消",null).setPositiveButton("恢复",(dialog,which)->executor.execute(()->{try{String text=read(backupFile().openRead());JSONObject obj=new JSONObject(text);if(!"XZY-BattleArchive".equals(obj.getString("Format")))throw new IOException("备份格式不匹配");write(dbFile(),text);callback("window.databaseRestored("+JSONObject.quote(text)+")");}catch(Exception e){status("恢复失败："+e.getMessage());}})).show());}
    }
    @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(request==EXPORT){final String text=exportText;exportText=null;if(result!=RESULT_OK||intent==null||intent.getData()==null||text==null){status("已取消导出");return;}final Uri uri=intent.getData();executor.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("无法写入文件");out.write(text.getBytes(StandardCharsets.UTF_8));status("已导出到所选文件");}catch(Exception e){status("导出失败："+e.getMessage());}});}else if(request==IMPORT&&result==RESULT_OK&&intent!=null){List<Uri> uris=new ArrayList<>();if(intent.getClipData()!=null)for(int i=0;i<intent.getClipData().getItemCount();i++)uris.add(intent.getClipData().getItemAt(i).getUri());else if(intent.getData()!=null)uris.add(intent.getData());executor.execute(()->{try{if(uris.size()>50)throw new IOException("单次最多选择 50 个文件");JSONArray files=new JSONArray();int total=0;for(Uri uri:uris){String text=read(getContentResolver().openInputStream(uri));total+=text.getBytes(StandardCharsets.UTF_8).length;if(total>MAX)throw new IOException("本批次文件超过 64 MB");files.put(text);}callback("window.importBatch("+files.toString()+")");}catch(Exception e){status("读取失败，本批次未导入："+e.getMessage());}});}else if(request==OFFICIAL&&result==RESULT_OK){executor.execute(()->{try{String text=read(new AtomicFile(new File(getFilesDir(),"official-export.json")).openRead());callback("window.importDatabase("+JSONObject.quote(text)+")");}catch(Exception e){status("官网结果读取失败："+e.getMessage());}});}}
    private void goBack(){callback("if(document.getElementById('overview').hidden){document.querySelector('nav button[data-tab=overview]').click()}else{Android.closeApp()}");}
    @Override public void onBackPressed(){goBack();}
    @Override protected void onDestroy(){executor.shutdownNow();rankExecutor.shutdownNow();if(web!=null){web.removeJavascriptInterface("Android");web.destroy();web=null;}super.onDestroy();}
}
